// Collect every Closed Won deal in the pipeline so we can look up which companies they belong to.
const pipeline = $('Fetch HubSpot Pipeline').first().json;
const wonStageIds = pipeline.stages
  .filter(function (s) { return s.metadata.isClosed === 'true' && Number(s.metadata.probability) === 1; })
  .map(function (s) { return s.id; });
const deals = $('Post to HubSpot Deals Search').all().flatMap(function (i) { return i.json.results || []; });
const wonIds = deals
  .filter(function (d) { return wonStageIds.indexOf(d.properties.dealstage) !== -1; })
  .map(function (d) { return { id: d.id }; });
// HubSpot rejects an empty batch, so send one placeholder id when there is nothing to look up.
return [{ json: { wonCount: wonIds.length, body: { inputs: wonIds.length ? wonIds : [{ id: '0' }] } } }];

// Turn the deal-to-company links into a unique list of company ids to read.
const links = ($input.first().json.results || []);
const ids = [];
links.forEach(function (l) {
  (l.to || []).forEach(function (t) {
    const id = String(t.toObjectId);
    if (ids.indexOf(id) === -1) ids.push(id);
  });
});
return [{ json: { companyCount: ids.length, body: {
  properties: ['name', 'industry', 'numberofemployees', 'hubspot_owner_id', 'hs_num_open_deals'],
  inputs: ids.length ? ids.map(function (id) { return { id: id }; }) : [{ id: '0' }]
} } }];

// Apply the hygiene rules to every open deal and find expansion candidates among Closed Won clients.
const cfg = $('Set HubSpot Parameters').first().json;
const portal = $('Fetch HubSpot Portal Details').first().json;
const pipeline = $('Fetch HubSpot Pipeline').first().json;
const owners = {};
($('Fetch Pipeline Owners').first().json.results || []).forEach(function (o) {
  owners[o.id] = [o.firstName, o.lastName].filter(Boolean).join(' ') || o.email;
});

const DAY = 86400000;
const now = Date.now();
const daysSince = function (iso) { return iso ? Math.floor((now - Date.parse(iso)) / DAY) : null; };
const daysUntil = function (iso) { return iso ? Math.ceil((Date.parse(iso) - now) / DAY) : null; };
const recordUrl = function (type, id) { return 'https://' + portal.uiDomain + '/contacts/' + portal.portalId + '/record/' + type + '/' + id; };

const stages = {};
pipeline.stages.forEach(function (s) { stages[s.id] = s; });
const isClosed = function (s) { return s && s.metadata.isClosed === 'true'; };
const isWon = function (s) { return isClosed(s) && Number(s.metadata.probability) === 1; };

const deals = $('Post to HubSpot Deals Search').all().flatMap(function (i) { return i.json.results || []; });
const openDeals = deals.filter(function (d) { return !isClosed(stages[d.properties.dealstage]); });

const findings = [];
openDeals.forEach(function (d) {
  const p = d.properties;
  const stage = stages[p.dealstage] || { label: 'Unknown stage', metadata: { probability: '0' } };
  const idle = daysSince(p.notes_last_updated || p.createdate);
  const inStage = daysSince(p.hs_v2_date_entered_current_stage);
  const closeIn = daysUntil(p.closedate);
  const amount = p.amount ? Number(p.amount) : null;
  const contacts = Number(p.num_associated_contacts || 0);
  const issues = [];
  if (closeIn !== null && closeIn < 0) issues.push({ code: 'past_close_date', text: 'Close date passed ' + (-closeIn) + ' days ago' });
  if (closeIn === null) issues.push({ code: 'missing_close_date', text: 'No close date' });
  if (idle !== null && idle >= cfg.staleDays) issues.push({ code: 'stale', text: 'No activity for ' + idle + ' days' });
  if (inStage !== null && inStage >= cfg.stuckDays) issues.push({ code: 'stuck_in_stage', text: 'In ' + stage.label + ' for ' + inStage + ' days' });
  if (amount === null) issues.push({ code: 'missing_amount', text: 'No amount' });
  if (!p.hubspot_owner_id) issues.push({ code: 'no_owner', text: 'No deal owner' });
  if (contacts === 0) issues.push({ code: 'no_contact', text: 'No contact associated' });
  if (!issues.length) return;
  findings.push({
    kind: 'deal',
    dealId: d.id,
    title: p.dealname || ('Deal ' + d.id),
    url: recordUrl('0-3', d.id),
    ownerId: p.hubspot_owner_id || null,
    ownerName: p.hubspot_owner_id ? (owners[p.hubspot_owner_id] || 'Owner ' + p.hubspot_owner_id) : 'Unassigned',
    stage: stage.label,
    stageProbability: Number(stage.metadata.probability),
    amount: amount,
    daysIdle: idle,
    daysInStage: inStage,
    daysUntilClose: closeIn,
    contacts: contacts,
    issues: issues,
    noteLookupDealId: d.id
  });
});

// Expansion: companies whose latest Closed Won deal is old enough and that have no open deal anywhere.
const links = ($('Fetch Won-Deal Companies').first().json.results || []);
const companyOfDeal = {};
links.forEach(function (l) {
  const first = (l.to || [])[0];
  if (first) companyOfDeal[String(l.from.id)] = String(first.toObjectId);
});
const companies = {};
($('Fetch Company Details').first().json.results || []).forEach(function (c) { companies[c.id] = c; });

const wonByCompany = {};
deals.filter(function (d) { return isWon(stages[d.properties.dealstage]); }).forEach(function (d) {
  const cid = companyOfDeal[d.id];
  if (!cid) return;
  (wonByCompany[cid] = wonByCompany[cid] || []).push(d);
});

const expansions = [];
Object.keys(wonByCompany).forEach(function (cid) {
  const company = companies[cid];
  if (!company) return;
  const won = wonByCompany[cid].sort(function (a, b) { return Date.parse(b.properties.closedate) - Date.parse(a.properties.closedate); });
  const sinceLastWin = daysSince(won[0].properties.closedate);
  const openDealsAnywhere = Number(company.properties.hs_num_open_deals || 0);
  if (sinceLastWin === null || sinceLastWin < cfg.expansionAfterDays || openDealsAnywhere > 0) return;
  const ownerId = company.properties.hubspot_owner_id || won[0].properties.hubspot_owner_id || null;
  expansions.push({
    kind: 'expansion',
    companyId: cid,
    title: company.properties.name || ('Company ' + cid),
    url: recordUrl('0-2', cid),
    ownerId: ownerId,
    ownerName: ownerId ? (owners[ownerId] || 'Owner ' + ownerId) : 'Unassigned',
    industry: company.properties.industry || 'Unknown',
    employees: company.properties.numberofemployees ? Number(company.properties.numberofemployees) : null,
    wonDeals: won.map(function (d) { return { name: d.properties.dealname, amount: Number(d.properties.amount || 0), daysSinceWon: daysSince(d.properties.closedate) }; }),
    totalWon: won.reduce(function (s, d) { return s + Number(d.properties.amount || 0); }, 0),
    daysSinceLastWin: sinceLastWin,
    issues: [{ code: 'expansion', text: 'Client for ' + sinceLastWin + ' days, no open deal' }],
    noteLookupDealId: won[0].id
  });
});

// Keep the most valuable items if the list is long, so Jev calls and the email stay manageable.
findings.sort(function (a, b) { return (b.amount || 0) - (a.amount || 0); });
const kept = findings.slice(0, cfg.maxFindings);
const stats = {
  pipelineName: pipeline.label,
  openDeals: openDeals.length,
  flaggedDeals: findings.length,
  truncated: findings.length > kept.length,
  valueFlagged: kept.reduce(function (s, f) { return s + (f.amount || 0); }, 0),
  expansionCandidates: expansions.length,
  currency: portal.companyCurrency || ''
};

const out = kept.concat(expansions).map(function (x) { return { json: Object.assign(x, { stats: stats }) }; });
if (!out.length) return [{ json: { kind: 'clean', stats: stats } }];
return out;

// Attach the latest note and build one Jev request per finding.
const base = $('Check for Items to Review').item.json;
const raw = (($json.results || [])[0] || {}).properties || {};
const lastNote = String(raw.hs_note_body || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1000);

let jevBody;
if (base.kind === 'deal') {
  jevBody = {
    model: 'jev-latest',
    state: {
      deal: base.title,
      stage: base.stage,
      stage_win_probability: base.stageProbability,
      amount: base.amount,
      days_since_last_activity: base.daysIdle,
      days_until_close_date: base.daysUntilClose === null ? 'not set' : base.daysUntilClose,
      associated_contacts: base.contacts,
      has_owner: Boolean(base.ownerId),
      detected_issues: base.issues.map(function (i) { return i.text; }),
      latest_note: lastNote || 'No notes logged'
    },
    questions: {
      at_risk: {
        type: 'noul',
        instructions: 'Is this deal at real risk of being lost or slipping, judging by the facts and the latest note?',
        criteria: { 'true': 'The buyer has gone quiet, there is a blocker, or the budget is gone', 'false': 'The buyer is engaged and there is a clear next step' }
      },
      next_action: {
        type: 'choice',
        instructions: 'Which single fix should the sales team apply to this deal now?',
        criteria: {
          push_close_date: 'The buyer is still engaged but the timeline moved, so the close date should move out',
          follow_up_task: 'The deal can be saved but the owner must re-engage the buyer or fix missing deal data',
          close_lost: 'The deal is effectively dead: long silence, frozen budget, or the buyer chose another option'
        }
      },
      push_days: {
        type: 'choice',
        instructions: 'If the close date moves, how far out should it move?',
        criteria: {
          '7': 'Signature is days away, a small slip',
          '14': 'A couple of weeks, for example procurement or legal review',
          '30': 'About a month, for example a security review or budget approval',
          '60': 'A quarter-scale delay, for example waiting for the next budget cycle'
        }
      }
    }
  };
} else {
  jevBody = {
    model: 'jev-latest',
    state: {
      client: base.title,
      industry: base.industry,
      employees: base.employees,
      won_deals: base.wonDeals,
      days_since_last_win: base.daysSinceLastWin,
      open_deals: 0,
      latest_note: lastNote || 'No notes logged'
    },
    questions: {
      play: {
        type: 'choice',
        instructions: 'What is the best expansion play for this existing client right now?',
        criteria: {
          upsell: 'Grow what they already bought: more seats, a higher tier or more hubs',
          cross_sell: 'Offer an adjacent service they do not have yet',
          check_in_first: 'Too early or unclear, book a success check-in before pitching anything'
        }
      },
      likelihood: {
        type: 'score',
        instructions: 'How likely is this client to buy more in the next quarter?',
        criteria: ['Low', 'Medium', 'High']
      }
    }
  };
}
return { json: Object.assign({}, base, { lastNote: lastNote, jevBody: jevBody }) };

// Turn Jev's answers (or the rule-based fallback) into concrete, reviewable HubSpot fixes.
const cfg = $('Set HubSpot Parameters').first().json;
const pipeline = $('Fetch HubSpot Pipeline').first().json;
const DAY = 86400000;
const now = Date.now();
const isoIn = function (d) { return new Date(now + d * DAY).toISOString().slice(0, 10); };
const clean = function (s) { return String(s).replace(/,/g, ' ').replace(/\s+/g, ' ').trim(); };
const esc = function (s) { return String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const money = function (n) { return n === null || n === undefined ? '—' : String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); };

const sorted = pipeline.stages.slice().sort(function (a, b) { return a.displayOrder - b.displayOrder; });
const firstStage = sorted.find(function (s) { return s.metadata.isClosed !== 'true'; });
const lostStage = sorted.find(function (s) { return s.metadata.isClosed === 'true' && Number(s.metadata.probability) === 0; });

const topOf = function (probs) {
  let best = null;
  Object.keys(probs || {}).forEach(function (k) { if (best === null || probs[k] > probs[best]) best = k; });
  return best;
};
const has = function (base, code) { return base.issues.some(function (i) { return i.code === code; }); };

// Deterministic fallback used when Jev is disabled, fails, or returns nothing usable.
const rulesForDeal = function (base) {
  if (base.daysIdle !== null && base.daysIdle >= cfg.staleDays * 4) return { action: 'close_lost', pushDays: null, atRisk: 1, confidence: null };
  if (has(base, 'past_close_date') || has(base, 'missing_close_date')) {
    if (base.daysIdle !== null && base.daysIdle < cfg.staleDays) return { action: 'push_close_date', pushDays: has(base, 'missing_close_date') ? 30 : 14, atRisk: 0.5, confidence: null };
  }
  return { action: 'follow_up_task', pushDays: null, atRisk: has(base, 'stale') ? 0.7 : 0.4, confidence: null };
};

const taskFor = function (base, atRisk) {
  const subject = has(base, 'stale') || has(base, 'past_close_date') ? 'Re-engage: ' + base.title
    : has(base, 'missing_close_date') ? 'Set a close date: ' + base.title
    : has(base, 'missing_amount') ? 'Add amount: ' + base.title
    : has(base, 'no_contact') ? 'Add buyer contact: ' + base.title
    : has(base, 'no_owner') ? 'Assign an owner: ' + base.title
    : 'Review deal: ' + base.title;
  const props = {
    hs_task_subject: subject,
    hs_task_body: 'Pipeline Watchdog found: ' + base.issues.map(function (i) { return i.text; }).join('; ') + '.',
    hs_timestamp: new Date(now + 2 * DAY).toISOString(),
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: atRisk >= 0.6 ? 'HIGH' : 'MEDIUM',
    hs_task_type: 'TODO'
  };
  if (base.ownerId) props.hubspot_owner_id = base.ownerId;
  return props;
};

const proposals = [];
$input.all().forEach(function (it, i) {
  const isBase = it.json.jevBody !== undefined;
  const base = isBase ? it.json : $('Prepare Jev Request').itemMatching(i).json;
  const answers = !isBase && it.json.answers ? it.json.answers : null;
  const jevError = !isBase && !answers ? (it.json.error && (it.json.error.message || it.json.error)) || 'no answer returned' : null;
  const source = answers ? 'Jev' : (cfg.useJev ? 'Rules (Jev unavailable: ' + String(jevError).slice(0, 80) + ')' : 'Rules (Jev disabled)');

  if (base.kind === 'deal') {
    let d;
    if (answers && answers.next_action && answers.next_action.choice) {
      d = {
        action: answers.next_action.choice,
        confidence: answers.next_action.confidence,
        atRisk: answers.at_risk ? answers.at_risk.noul : null,
        pushDays: answers.push_days && answers.push_days.choice ? Number(answers.push_days.choice) : 14
      };
    } else {
      d = rulesForDeal(base);
    }
    let guardrail = '';
    // Guardrail: never propose closing a deal that had activity recently.
    if (d.action === 'close_lost' && (base.daysIdle === null || base.daysIdle < cfg.staleDays)) {
      d.action = 'follow_up_task';
      guardrail = 'Close suggestion downgraded: the deal had recent activity.';
    }
    let actionLabel, apply;
    if (d.action === 'push_close_date') {
      const date = isoIn(d.pushDays || 14);
      actionLabel = 'Move close date to ' + date + ' (+' + (d.pushDays || 14) + 'd)';
      apply = { method: 'PATCH', url: 'https://api.hubapi.com/crm/v3/objects/deals/' + base.dealId, body: { properties: { closedate: date } } };
    } else if (d.action === 'close_lost') {
      actionLabel = 'Move to ' + (lostStage ? lostStage.label : 'Closed Lost');
      apply = { method: 'PATCH', url: 'https://api.hubapi.com/crm/v3/objects/deals/' + base.dealId, body: { properties: { dealstage: lostStage ? lostStage.id : '', closed_lost_reason: 'No activity for ' + base.daysIdle + ' days. Closed by Pipeline Watchdog after reviewer approval.' } } };
    } else {
      const props = taskFor(base, d.atRisk || 0);
      actionLabel = 'Create task: ' + props.hs_task_subject;
      apply = { method: 'POST', url: 'https://api.hubapi.com/crm/v3/objects/tasks', body: { properties: props, associations: [{ to: { id: base.dealId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 216 }] }] } };
    }
    const lowConfidence = d.confidence !== null && d.confidence !== undefined && d.confidence < cfg.jevMinConfidence;
    proposals.push({
      kind: 'deal', title: base.title, url: base.url, owner: base.ownerName, stage: base.stage, amount: base.amount,
      issues: base.issues.map(function (x) { return x.text; }), lastNote: base.lastNote,
      atRisk: d.atRisk, confidence: d.confidence, source: source, guardrail: guardrail, lowConfidence: lowConfidence,
      actionLabel: actionLabel, apply: apply,
      category: (has(base, 'stale') || has(base, 'stuck_in_stage')) ? 'cold' : (has(base, 'past_close_date') || has(base, 'missing_close_date')) ? 'closedate' : 'data'
    });
  } else {
    let play, confidence = null, likelihood = 'Medium';
    if (answers && answers.play && answers.play.choice) {
      play = answers.play.choice;
      confidence = answers.play.confidence;
      if (answers.likelihood) {
        const k = topOf(answers.likelihood.probabilities);
        likelihood = (answers.likelihood.legend && k !== null && answers.likelihood.legend[k]) || likelihood;
      }
    } else {
      play = 'check_in_first';
    }
    const playText = { upsell: 'Upsell', cross_sell: 'Cross-sell', check_in_first: 'Success check-in first' }[play] || play;
    let actionLabel, apply, estimate = null;
    if (play === 'upsell' || play === 'cross_sell') {
      estimate = Math.max(500, Math.round(base.totalWon * (play === 'upsell' ? 0.4 : 0.3) / 500) * 500);
      const props = {
        dealname: 'Expansion – ' + base.title, pipeline: pipeline.id, dealstage: firstStage.id, dealtype: 'existingbusiness',
        amount: String(estimate), closedate: isoIn(60),
        description: 'Suggested by Pipeline Watchdog. Play: ' + playText + '. Likelihood: ' + likelihood + '. Estimate based on past purchases, adjust after discovery.'
      };
      if (base.ownerId) props.hubspot_owner_id = base.ownerId;
      actionLabel = 'Create ' + playText.toLowerCase() + ' deal (~' + money(estimate) + ')';
      apply = { method: 'POST', url: 'https://api.hubapi.com/crm/v3/objects/deals', body: { properties: props, associations: [{ to: { id: base.companyId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 5 }] }] } };
    } else {
      const props = {
        hs_task_subject: 'Book a success check-in: ' + base.title,
        hs_task_body: 'Client for ' + base.daysSinceLastWin + ' days with no open deal. Check satisfaction and needs before proposing anything new.',
        hs_timestamp: new Date(now + 3 * DAY).toISOString(), hs_task_status: 'NOT_STARTED', hs_task_priority: 'MEDIUM', hs_task_type: 'CALL'
      };
      if (base.ownerId) props.hubspot_owner_id = base.ownerId;
      actionLabel = 'Create task: book a success check-in';
      apply = { method: 'POST', url: 'https://api.hubapi.com/crm/v3/objects/tasks', body: { properties: props, associations: [{ to: { id: base.companyId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 192 }] }] } };
    }
    proposals.push({
      kind: 'expansion', title: base.title, url: base.url, owner: base.ownerName, amount: base.totalWon, estimate: estimate,
      issues: base.issues.map(function (x) { return x.text; }), lastNote: base.lastNote, play: playText, likelihood: likelihood,
      confidence: confidence, source: source, guardrail: '', lowConfidence: confidence !== null && confidence < cfg.jevMinConfidence,
      actionLabel: actionLabel, apply: apply,
      category: 'expansion'
    });
  }
});

// Group by the main problem, then number the fixes in that order so the email, the form and the checkboxes match.
const SECTIONS = [
  { key: 'cold', title: 'Going cold', hint: 'No recent activity or stuck in a stage' },
  { key: 'closedate', title: 'Close date slipped or missing', hint: 'The forecast date is in the past or not set' },
  { key: 'data', title: 'Missing data', hint: 'Amount, owner or buyer contact is missing' },
  { key: 'expansion', title: 'Expansion opportunities', hint: 'Clients with no open deal' }
];
const order = SECTIONS.map(function (x) { return x.key; });
proposals.sort(function (a, b) { return order.indexOf(a.category) - order.indexOf(b.category); });
proposals.forEach(function (p, idx) {
  p.n = idx + 1;
  p.label = clean('#' + p.n + ' ' + p.title + ' → ' + p.actionLabel);
});

const stats = $('Prepare Jev Request').first().json.stats;
const pct = function (x) { return x === null || x === undefined ? '—' : Math.round(x * 100) + '%'; };
const link = function (p) { return '<a href="' + p.url + '">' + esc(p.title) + '</a>'; };

const verdict = function (p) {
  const conf = p.confidence !== null && p.confidence !== undefined ? ' · confidence ' + pct(p.confidence) : '';
  const main = p.kind === 'deal' ? 'At risk: ' + pct(p.atRisk) : esc(p.play) + ' · likelihood ' + esc(p.likelihood);
  return main + '<br><span style="color:#6b7280">' + esc(p.source) + conf + '</span>' +
    (p.lowConfidence ? '<br><b>Low confidence, check before approving</b>' : '') +
    (p.guardrail ? '<br><i>' + esc(p.guardrail) + '</i>' : '');
};
const context = function (p) {
  return p.kind === 'deal' ? esc(p.stage) + ' · ' + money(p.amount) + ' · ' + esc(p.owner) : 'Won so far: ' + money(p.amount) + ' · ' + esc(p.owner);
};
const inSection = function (key) { return proposals.filter(function (p) { return p.category === key; }); };

const headline = '<b>' + esc(stats.pipelineName) + '</b>: ' + stats.openDeals + ' open deals scanned, ' + stats.flaggedDeals + ' need attention (' + money(stats.valueFlagged) + ' ' + esc(stats.currency) + '), ' + stats.expansionCandidates + ' expansion opportunities.' + (stats.truncated ? ' Showing the ' + cfg.maxFindings + ' largest deals.' : '');

const preselected = proposals.filter(function (p) { return !p.lowConfidence && !p.guardrail; }).map(function (p) { return p.label; });
// Forms cannot run scripts, so "select all / none" is a separate choice that overrides the checkboxes.
const formFields = [
  { fieldType: 'html', elementName: 'summary', html: '<div style="text-align:left"><p>' + headline + '</p><p style="color:#6b7280;font-size:12px">Nothing changes in HubSpot until you submit this form.</p></div>' },
  { fieldLabel: 'Which fixes should be applied?', fieldType: 'radio', fieldOptions: { values: [{ option: 'Only the ticked fixes below' }, { option: 'All proposed fixes' }, { option: 'None, change nothing' }] }, defaultValue: 'Only the ticked fixes below', requiredField: true }
];
const checkboxLabels = [];
const card = 'border:1px solid #e5e7eb;border-radius:8px;padding:10px 12px;margin:14px 0 4px;text-align:left;font-size:13px;line-height:1.45;';
SECTIONS.forEach(function (sec) {
  const items = inSection(sec.key);
  if (!items.length) return;
  formFields.push({ fieldType: 'html', elementName: 'section_' + sec.key, html: '<div style="text-align:left"><h3 style="margin:28px 0 2px">' + esc(sec.title) + ' (' + items.length + ')</h3><p style="margin:0;color:#6b7280;font-size:12px">' + esc(sec.hint) + '</p></div>' });
  // One card per record with its own checkbox right underneath, so each problem sits next to its fix.
  items.forEach(function (p) {
    const fieldLabel = 'Fix #' + p.n;
    checkboxLabels.push({ field: fieldLabel, n: p.n });
    formFields.push({ fieldType: 'html', elementName: 'card_' + p.n, html: '<div style="' + card + '"><b>#' + p.n + ' ' + link(p) + '</b> <span style="color:#6b7280">' + context(p) + '</span><br>' +
      '<span>Found: ' + p.issues.map(esc).join(' · ') + '</span><br>' +
      '<span>Verdict: ' + verdict(p).replace(/<br>/g, ' · ') + '</span></div>' });
    formFields.push({ fieldLabel: fieldLabel, fieldType: 'checkbox', fieldOptions: { values: [{ option: p.label }] }, defaultValue: preselected.indexOf(p.label) !== -1 ? p.label : '' });
  });
});

// Greet the reviewer by the first name of the HubSpot owner with the same email address.
const reviewerOwner = ($('Fetch Pipeline Owners').first().json.results || []).find(function (o) { return String(o.email || '').toLowerCase() === String(cfg.reviewerEmail).toLowerCase(); });
const greetingName = reviewerOwner && reviewerOwner.firstName ? reviewerOwner.firstName : 'team';
