// Map the ticked checkboxes back to the proposed fixes.
const resp = $json.data || $json;
const decided = $('Determine HubSpot Fixes').first().json;
const tickedNumbers = decided.checkboxLabels.filter(function (c) {
  const v = resp[c.field];
  return Array.isArray(v) ? v.length > 0 : Boolean(v);
}).map(function (c) { return c.n; });
const mode = resp['Which fixes should be applied?'] || 'Only the ticked fixes below';
const proposals = decided.proposals;
const approved = mode === 'All proposed fixes' ? proposals
  : mode === 'None, change nothing' ? []
  : proposals.filter(function (p) { return tickedNumbers.indexOf(p.n) !== -1; });
if (!approved.length) {
  const answered = resp['Which fixes should be applied?'] !== undefined;
  const reason = mode === 'None, change nothing' ? 'You chose to change nothing.' : answered ? 'No fixes were ticked.' : 'No response before the review window closed.';
  return [{ json: { noneApproved: true, reason: reason } }];
}
return approved.map(function (p) { return { json: p }; });

// Pair each HubSpot response with the fix that caused it and build the results email.
const esc = function (s) { return String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const rows = $input.all().map(function (it, i) {
  const fix = $('Align Approved Fixes').itemMatching(i).json;
  const ok = !it.json.error && (it.json.id || it.json.properties);
  const detail = ok ? 'Done' : 'Failed: ' + esc((it.json.error && (it.json.error.message || it.json.error.description)) || 'unknown error');
  return { ok: Boolean(ok), html: '<li>' + (ok ? '✅ ' : '⚠️ ') + '<a href="' + fix.url + '">' + esc(fix.title) + '</a>: ' + esc(fix.actionLabel) + ' — ' + detail + '</li>' };
});
const okCount = rows.filter(function (r) { return r.ok; }).length;
// Same greeting as the review email: first name of the HubSpot owner with the reviewer's email address.
const cfg = $('Set HubSpot Parameters').first().json;
const reviewerOwner = ($('Fetch Pipeline Owners').first().json.results || []).find(function (o) { return String(o.email || '').toLowerCase() === String(cfg.reviewerEmail).toLowerCase(); });
const greetingName = reviewerOwner && reviewerOwner.firstName ? reviewerOwner.firstName : 'team';
return [{ json: {
  subject: 'Pipeline Watchdog: ' + okCount + ' of ' + rows.length + ' fixes applied',
  html: '<div style="text-align:left;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.45;color:#111827;max-width:640px"><p>Dear ' + esc(greetingName) + ',</p><p>' + okCount + ' of ' + rows.length + ' approved fixes were applied in HubSpot.</p><ul>' + rows.map(function (r) { return r.html; }).join('') + '</ul>' +
    (okCount < rows.length ? '<p>Failed fixes were not retried. Check the linked records or the n8n execution log.</p>' : '') +
    '<p>Best regards,<br>Your n8n &amp; HubSpot AI automation bot</p></div>'
} }];
